    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and all Materials are and shall be wholly original with ProdCo and its personnel, are fully protected by copyright under applicable law, and do not and shall not infringe upon or violate any copyright, trademark, patent or other intellectual property right of any third party.', ARRAY['represents warrants','Program','Materials','wholly original','ProdCo','personnel','fully protected','copyright','applicable law','not infringe','violate','intellectual property','third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Standard originality and copyright representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard unqualified representation of originality and copyright protection. Covers Program and Materials with appropriate breadth. No knowledge qualifiers that would weaken the representation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (a) all literary, dramatic, musical and artistic elements of the Program are original works of authorship created by ProdCo or its employees and contractors; (b) all such works are protected by copyright; and (c) ProdCo has the full right and authority to grant all rights contemplated herein.', ARRAY['represents warrants','literary','dramatic','musical','artistic','original works','authorship','created by ProdCo','employees','contractors','protected by copyright','full right','authority','grant rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Enumerated elements with authority representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific types of copyrightable elements and includes authority representation. Comprehensive coverage of creative elements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original and were independently created without copying or derivation from any pre-existing work not owned or fully licensed by ProdCo. All copyrightable elements of the Program shall be entitled to full copyright protection under the laws of the United States and all other applicable jurisdictions.', ARRAY['represents warrants','Program','Materials','original','independently created','without copying','derivation','pre-existing work','owned','licensed','copyrightable elements','full copyright protection','United States','jurisdictions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Independent creation with multi-jurisdiction protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Emphasizes independent creation and addresses pre-existing works carveout for owned/licensed materials. Multi-jurisdiction copyright protection representation is appropriate for global exploitation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that all elements of the Program, including without limitation the screenplay, teleplay, dialogue, characters, storylines, music, and visual elements, are original creations fully protected by copyright, and that ProdCo owns or controls all rights necessary for Amazon''s exploitation of the Program as contemplated herein.', ARRAY['represents warrants','elements','Program','screenplay','teleplay','dialogue','characters','storylines','music','visual elements','original','copyright','ProdCo owns','controls','rights','exploitation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Detailed enumeration of Program elements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed enumeration of specific Program elements covered by originality representation. Includes both creation and rights control aspects."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (i) the Program and all Materials constitute original works of authorship; (ii) the Program and Materials are copyrightable under the Copyright Act of 1976, as amended; (iii) no portion of the Program or Materials is in the public domain; and (iv) no AI-generated content is included in the Program or Materials.', ARRAY['represents warrants','original works','authorship','copyrightable','Copyright Act 1976','no public domain','no AI-generated content']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Includes AI-generated content representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes important post-2023 representation regarding AI-generated content, addressing copyrightability concerns. Public domain exclusion protects against unprotectable elements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is an original audiovisual work created by human authors and is entitled to full copyright protection. ProdCo further represents that all creative contributions to the Program were made by natural persons and not by artificial intelligence or machine learning systems.', ARRAY['represents warrants','original audiovisual work','human authors','full copyright protection','creative contributions','natural persons','not artificial intelligence','machine learning']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Human authorship representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit human authorship representation addresses US Copyright Office position that AI-generated works lack human authorship for copyright purposes. Critical for protecting Program copyrightability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Programme and all Materials are original works fully protected by copyright under the Copyright, Designs and Patents Act 1988 and all applicable international copyright conventions. ProdCo has caused all necessary assignments and waivers to be executed to vest full copyright ownership in Amazon.', ARRAY['represents warrants','Programme','Materials','original','copyright','CDPA 1988','international conventions','assignments','waivers','vest','ownership','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "UK-specific copyright representation", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate reference to CDPA 1988 and international conventions. Includes representation regarding assignments and waivers necessary for UK copyright vesting."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original and copyrightable, except for any third-party materials that have been cleared for use in the Program pursuant to licenses listed in Exhibit C, which licenses grant rights sufficient for Amazon''s contemplated exploitation.', ARRAY['represents warrants','original','copyrightable','except','third-party materials','cleared','licenses','Exhibit C','sufficient','exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Exception for scheduled licensed materials", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for Exhibit C licensed materials is reasonable if Exhibit C is properly reviewed. Legal must verify that scheduled licenses provide sufficient rights for exploitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is original and protected by copyright. Notwithstanding the foregoing, this representation shall not apply to any stock footage, music, or visual effects elements sourced from third-party libraries, which ProdCo represents have been properly licensed for use in the Program.', ARRAY['represents warrants','original','copyright','notwithstanding','not apply','stock footage','music','visual effects','third-party libraries','properly licensed']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Stock and library material carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for stock and library materials with licensing representation is practical for productions using licensed elements. Legal should verify licensing is adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original works protected by copyright. ProdCo shall provide Amazon with a complete chain of title package evidencing all rights, and Amazon''s acceptance of such package shall not diminish ProdCo''s representations hereunder.', ARRAY['represents warrants','original','copyright','chain of title package','evidencing','rights','acceptance','not diminish','representations']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Chain of title delivery with preservation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Chain of title delivery obligation is standard. Clarification that Amazon''s acceptance doesn''t diminish representations preserves Amazon''s recourse. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is original and copyrightable. This representation is made as of the Effective Date and as of the date of final delivery of the Program to Amazon, but does not extend to any period thereafter.', ARRAY['represents warrants','original','copyrightable','as of Effective Date','as of final delivery','does not extend','thereafter']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Time-limited representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Time-limited representation through delivery may be acceptable as originality is primarily a creation-time issue. Legal should assess whether post-delivery limitation creates gap."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original and protected by copyright. In the event any third party asserts a claim challenging the originality of any Program element, ProdCo shall immediately notify Amazon and cooperate fully in the defense of such claim.', ARRAY['represents warrants','original','copyright','third party','asserts claim','challenging originality','immediately notify','cooperate','defense']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Claim notification and cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notification and cooperation obligations enhance Amazon''s ability to respond to claims. These are reasonable procedural additions that don''t weaken the substantive representation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is original, copyrightable, and was created without the use of generative AI tools for substantive creative content. For clarity, this prohibition does not apply to AI-assisted tools used solely for administrative or technical purposes (e.g., scheduling, color correction presets).', ARRAY['represents warrants','original','copyrightable','without','generative AI','substantive creative','prohibition','not apply','AI-assisted','administrative','technical']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "AI carveout for administrative/technical", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between creative AI (prohibited) and administrative/technical AI may be reasonable. Legal should define boundary precisely and confirm examples are appropriately narrow."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the best of ProdCo''s knowledge, the Program and Materials are original and protected by copyright. ProdCo has not received any notice of any claim challenging the originality of the Program.', ARRAY['to the best of knowledge','Program','Materials','original','copyright','not received notice','claim','challenging originality']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier on originality", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on originality representation is completely unacceptable. ProdCo creates the content and must warrant originality absolutely, not merely to its knowledge."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is believed to be original but makes no warranty regarding copyright protection or the absence of infringement claims. Amazon acknowledges that content creation involves inherent risks of inadvertent similarity to existing works.', ARRAY['represents','believed to be original','no warranty','copyright protection','absence of claims','acknowledges','inherent risks','inadvertent similarity']::text[], '{"doc": "Counterparty_Proposal", "section": "Representations and Warranties", "note": "Disclaimer of originality warranty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Disclaiming warranty on originality and copyright shifts all creation risk to Amazon. Acknowledgment of ''inherent risks'' undermines entire chain of title protection. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is original and copyrightable, provided that this representation shall not apply to any element that ProdCo in good faith believed was in the public domain or otherwise available for use.', ARRAY['represents','original','copyrightable','provided','not apply','good faith believed','public domain','available for use']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Good faith belief exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Good faith belief exception allows ProdCo to avoid representation based on subjective belief. Public domain determinations require proper clearance, not good faith assumptions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that, except as disclosed in the attached Schedule of Known Issues, the Program is original and protected by copyright. Amazon has reviewed the Schedule of Known Issues and accepts the risks identified therein.', ARRAY['represents warrants','except as disclosed','Schedule of Known Issues','original','copyright','reviewed','accepts risks']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Carveout for known issues", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Open-ended carveout for ''Known Issues'' schedule could exclude significant problems. Amazon cannot ''accept risks'' of undisclosed scope. Issues must be resolved, not scheduled."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is substantially original. Minor similarities to existing works that do not constitute actionable infringement shall not be deemed a breach of this representation.', ARRAY['represents','substantially original','minor similarities','existing works','not actionable infringement','not deemed breach']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Substantial originality with similarities carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Substantially original'' with carveout for ''minor similarities'' waters down the representation. Determining what is ''minor'' or ''actionable'' creates litigation risk."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is original to the extent practicable given industry realities. ProdCo acknowledges that certain genre conventions, stock characters, and common plot elements may appear in multiple works and do not constitute lack of originality.', ARRAY['represents','original','to the extent practicable','industry realities','genre conventions','stock characters','common plot elements','not constitute','lack of originality']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Industry realities qualification", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''To the extent practicable'' qualification and broad carveouts for genre conventions significantly weaken originality representation. Creates ambiguity that could excuse infringement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is original. This representation shall survive for a period of three (3) years following delivery, after which it shall expire and be of no further force or effect.', ARRAY['represents','original','survive','three years','following delivery','expire','no further force effect']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Three-year survival limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Three-year survival limit on originality representation is completely inadequate given perpetual exploitation. Originality claims can surface decades after release. Must survive indefinitely."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials do not and shall not: (a) infringe any copyright, trademark, patent or other intellectual property right; (b) violate any right of privacy or publicity; (c) constitute defamation, libel or slander; or (d) violate any other right of any third party.', ARRAY['represents warrants','Program','Materials','not infringe','copyright','trademark','patent','intellectual property','privacy','publicity','defamation','libel','slander','violate','third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Comprehensive non-infringement representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive representation covering IP infringement, privacy/publicity, and defamation. Catch-all for other third-party rights provides complete coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that neither the Program nor any Materials infringe, violate or misappropriate any intellectual property rights, rights of privacy, rights of publicity, moral rights, or any contractual or other rights of any person or entity anywhere in the world.', ARRAY['represents warrants','Program','Materials','not infringe','violate','misappropriate','intellectual property','privacy','publicity','moral rights','contractual rights','anywhere in world']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Worldwide scope with misappropriation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes misappropriation (relevant for trade secrets and right of publicity in some states) and worldwide scope. Comprehensive protection for global exploitation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (i) the Program does not defame any person; (ii) the Program does not invade any person''s right of privacy or publicity; (iii) the Program does not infringe any copyright, trademark or other intellectual property right; and (iv) ProdCo has obtained all necessary consents, releases and clearances from any living person depicted or referred to in the Program.', ARRAY['represents warrants','not defame','not invade','privacy','publicity','not infringe','copyright','trademark','intellectual property','obtained','consents','releases','clearances','living person','depicted','referred to']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Includes consent/release representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes representation regarding obtaining consents and releases from depicted persons, addressing practical clearance requirements for documentaries and biopics."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not contain any material that is defamatory, libelous, slanderous, obscene, or that violates any right of privacy, right of publicity, or any other personal or proprietary right of any third party. This representation extends to all territories in which Amazon may exploit the Program.', ARRAY['represents warrants','Program','not contain','defamatory','libelous','slanderous','obscene','privacy','publicity','personal','proprietary','third party','all territories','exploit']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Territorial scope with obscenity", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes obscenity in addition to standard claims and explicitly extends to all exploitation territories. Comprehensive territorial coverage is essential for global streaming."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that neither the development, production, nor exploitation of the Program will infringe any third-party rights, including copyrights, trademarks, trade secrets, rights of privacy, rights of publicity, moral rights, or any contractual rights, and will not result in defamation of any person or entity.', ARRAY['represents warrants','development','production','exploitation','not infringe','third-party rights','copyrights','trademarks','trade secrets','privacy','publicity','moral rights','contractual','defamation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Covers development through exploitation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers entire lifecycle from development through exploitation, ensuring representation applies to all phases. Includes trade secrets which is important for format and idea protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights and does not contain any material that is false, misleading, defamatory or that invades any right of privacy or publicity. ProdCo has conducted appropriate legal review of the Program for defamation and privacy concerns and has addressed all issues identified in such review.', ARRAY['represents warrants','not infringe','not contain','false','misleading','defamatory','privacy','publicity','legal review','defamation','privacy concerns','addressed issues']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Legal review representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes representation regarding legal review (script clearance) and issue resolution. Important for documentary or fact-based content where defamation risk is elevated."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any intellectual property rights or violate any privacy, publicity, or defamation laws of any jurisdiction. Without limiting the foregoing, ProdCo represents that it has obtained valid written releases from all recognizable persons appearing in the Program.', ARRAY['represents warrants','not infringe','intellectual property','not violate','privacy','publicity','defamation','any jurisdiction','valid written releases','recognizable persons','appearing']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Written releases for appearing persons", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Requires valid written releases from all recognizable persons, providing documented protection against privacy and publicity claims from on-screen talent."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights or constitute defamation. Notwithstanding the foregoing, ProdCo does not represent or warrant that the Program will not be the subject of claims; ProdCo represents only that any such claims would be without merit.', ARRAY['represents warrants','not infringe','defamation','notwithstanding','not represent','not be subject of claims','claims without merit']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "No claim-free representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between meritless claims and no-claims is technically accurate but may create interpretive issues. Legal should assess whether this affects indemnity coverage."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights. With respect to documentary content, ProdCo represents that it has conducted standard script clearance review and has implemented recommendations of clearance counsel, but acknowledges that documentary content inherently carries elevated clearance risk.', ARRAY['represents warrants','not infringe','documentary content','script clearance review','implemented recommendations','clearance counsel','acknowledges','elevated clearance risk']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Documentary clearance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Documentary-specific acknowledgment of elevated risk may be acceptable if combined with clearance process representation. Legal should confirm indemnity remains fully applicable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe or violate any third-party rights. This representation is made subject to the E&O Insurance Coverage Exclusions set forth in Exhibit E, which Amazon has reviewed and accepted.', ARRAY['represents warrants','not infringe','violate','third-party rights','subject to','E&O Insurance','Coverage Exclusions','Exhibit E','reviewed','accepted']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "E&O exclusions incorporated", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Incorporating E&O exclusions may be acceptable if Amazon has actually reviewed and accepted specific exclusions. Legal must confirm Exhibit E contents are appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any intellectual property right or constitute defamation, libel, slander, or invasion of privacy. If the Program is based on or inspired by true events, ProdCo has taken reasonable steps to verify factual accuracy and to fictionalize appropriately.', ARRAY['represents warrants','not infringe','intellectual property','defamation','libel','slander','invasion of privacy','based on true events','reasonable steps','verify accuracy','fictionalize']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "True events verification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reasonable steps for true-events content is pragmatic acknowledgment of fact-based production realities. Legal should confirm this doesn''t weaken substantive representation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any third-party rights, defame any person, or violate any privacy or publicity right. ProdCo shall maintain errors and omissions insurance with coverage of not less than $3,000,000 per occurrence covering claims arising from the Program.', ARRAY['represents warrants','not infringe','defame','privacy','publicity','E&O insurance','$3,000,000','per occurrence','claims','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "E&O insurance requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "E&O insurance requirement provides additional protection layer. $3M per occurrence is reasonable minimum. Legal should confirm coverage terms are adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program does not infringe any rights or violate defamation laws. With respect to any real persons referenced in the Program, ProdCo has obtained appropriate life story rights, name and likeness rights, and releases as required under applicable law.', ARRAY['represents','not infringe','defamation','real persons','referenced','life story rights','name and likeness','releases','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Life story rights representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Life story rights representation is appropriate for biographical content. ''As required under applicable law'' provides some flexibility. Legal should confirm for specific production."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the best of ProdCo''s knowledge, after reasonable inquiry, the Program does not infringe any copyright or trademark, defame any person, or violate any right of privacy or publicity.', ARRAY['to the best of knowledge','reasonable inquiry','not infringe','copyright','trademark','defame','privacy','publicity']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier on non-infringement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on non-infringement representation is fundamentally unacceptable. ProdCo creates the content and must warrant non-infringement absolutely, not merely based on its knowledge or inquiry."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program does not, to ProdCo''s knowledge, infringe any intellectual property rights or defame any living person. ProdCo makes no representation regarding deceased persons or regarding rights under laws of jurisdictions outside the United States.', ARRAY['represents','to knowledge','not infringe','intellectual property','defame','living person','no representation','deceased persons','outside United States']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier with deceased/foreign carveouts", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier combined with exclusion of deceased persons and foreign jurisdictions creates massive gaps. Deceased persons'' estates have rights; international exploitation requires worldwide protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program does not infringe any rights. However, given the creative nature of content production, ProdCo cannot guarantee that no third party will ever assert a claim, and Amazon agrees to share equally in the defense costs of any such claim.', ARRAY['represents','not infringe','creative nature','cannot guarantee','no claim','Amazon','share equally','defense costs']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Shared defense costs", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring Amazon to share defense costs for claims arising from ProdCo''s content inverts the indemnity structure. ProdCo must bear full defense costs for its representations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program does not infringe any rights, except that this representation shall not apply to any claim based on (i) matters of public record, (ii) statements of opinion, or (iii) fair use or fair dealing.', ARRAY['represents','not infringe','except','not apply','public record','statements of opinion','fair use','fair dealing']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Broad exceptions to representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exceptions for public record, opinion, and fair use are legal defenses that should be asserted, not carveouts from the representation. These exceptions could justify almost any infringement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program does not infringe any intellectual property rights. ProdCo does not represent or warrant that the Program does not defame any person, as defamation is a matter of legal interpretation and factual analysis that ProdCo cannot definitively determine.', ARRAY['represents','not infringe','intellectual property','does not represent','warrant','defame','legal interpretation','factual analysis','cannot determine']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Defamation representation excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding defamation from the representation creates enormous exposure for fact-based or commentary content. ProdCo must warrant against defamation regardless of interpretive challenges."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program does not infringe any rights. Any claim asserted more than two (2) years after initial release of the Program shall be deemed waived for purposes of this representation, and ProdCo shall have no liability for such late-arising claims.', ARRAY['represents','not infringe','claim','two years','initial release','deemed waived','no liability','late-arising claims']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Two-year claim cutoff", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Two-year claim cutoff is completely inadequate. Infringement and defamation claims can surface years after release and may have longer statutes of limitation. Must survive indefinitely."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and all Materials are free and clear of any and all liens, claims, encumbrances, restrictions, or rights of any third party, and that no third party has any right, title, interest, claim or lien in or to the Program or Materials.', ARRAY['represents warrants','Program','Materials','free and clear','liens','claims','encumbrances','restrictions','rights','third party','no right','title','interest','lien']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Standard no-encumbrance representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard unqualified representation that Program and Materials are unencumbered. Essential for ensuring Amazon receives clean chain of title without third-party claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (a) ProdCo has full right and authority to enter into this Agreement and grant all rights herein; (b) no third party has any right, title, interest or claim in or to the Program or Materials; (c) the Program and Materials are not subject to any lien, charge, security interest or encumbrance; and (d) ProdCo has not granted and will not grant any rights inconsistent with the rights granted to Amazon.', ARRAY['represents warrants','full right','authority','enter into','grant rights','no third party','right title interest claim','not subject to','lien','charge','security interest','encumbrance','not granted','inconsistent rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Comprehensive authority and encumbrance representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive representation covering authority, third-party claims, encumbrances, and inconsistent grants. Essential protection against competing claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the rights granted hereunder are free of any adverse claim, lien, or encumbrance. No person or entity other than Amazon has or shall have any right to exploit the Program in any manner or to receive any proceeds from such exploitation.', ARRAY['represents warrants','rights granted','free of','adverse claim','lien','encumbrance','no person entity','other than Amazon','right to exploit','receive proceeds']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Exploitation and proceeds protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses both exploitation rights and proceeds, protecting against revenue claims from third parties. Important for clean ownership."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that no option, first-look, first-negotiation, or other preferential right has been granted to any third party with respect to the Program, the underlying rights, or any sequel, prequel, spinoff, or derivative thereof. ProdCo has the unencumbered right to grant Amazon all rights contemplated herein.', ARRAY['represents warrants','no option','first-look','first-negotiation','preferential right','third party','Program','underlying rights','sequel','prequel','spinoff','derivative','unencumbered','grant','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "No preferential rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specifically addresses preferential rights (options, first-looks) which could encumber sequel/derivative rights. Essential for franchise protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are not subject to any agreement, commitment, or understanding with any third party that would in any way restrict, limit, or impair Amazon''s rights hereunder or Amazon''s ability to fully exploit the Program throughout the universe in perpetuity.', ARRAY['represents warrants','Program','Materials','not subject to','agreement','commitment','understanding','third party','restrict','limit','impair','Amazon''s rights','exploit','universe','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "No restrictive agreements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses any form of restrictive agreement, not just formal encumbrances. Protects Amazon against informal commitments that could impair exploitation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that it has not assigned, pledged, hypothecated, or otherwise encumbered any rights in the Program or Materials, and that it shall not do so during the term of this Agreement or at any time thereafter. Any purported assignment or encumbrance in violation of this provision shall be void.', ARRAY['represents warrants','not assigned','pledged','hypothecated','encumbered','rights','Program','Materials','shall not','purported','void']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Anti-encumbrance with void provision", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes forward-looking covenant and void provision for violations. Provides strong protection against future encumbrances."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and all underlying rights are free from all defects in chain of title. ProdCo has valid and complete documentation evidencing ProdCo''s ownership or control of all necessary rights, which documentation shall be delivered to Amazon upon request.', ARRAY['represents warrants','Program','underlying rights','free from','defects','chain of title','valid','complete documentation','ownership','control','delivered','upon request']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Chain of title documentation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Representation regarding complete chain of title documentation with delivery requirement enables Amazon verification of clean title."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is free and clear of all encumbrances, except for customary guild and union residual obligations which are standard in the industry and do not affect Amazon''s exploitation rights.', ARRAY['represents warrants','Program','free and clear','encumbrances','except','guild','union','residual obligations','industry standard','not affect','exploitation rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Guild residuals carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Guild residual carveout is industry-standard and doesn''t affect exploitation rights. Legal should confirm residual obligations are truly standard and non-interfering."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is free of encumbrances. The parties acknowledge that certain talent agreements may contain standard provisions regarding credit, compensation adjustments, and approval rights that are customary in the entertainment industry and have been disclosed to Amazon.', ARRAY['represents','free of encumbrances','acknowledge','talent agreements','standard provisions','credit','compensation adjustments','approval rights','customary','disclosed']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Talent agreement acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment of disclosed talent agreement provisions may be acceptable if disclosures are complete and provisions are truly customary. Legal must verify disclosures."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is free of liens and encumbrances. Any contingent compensation, profit participation, or backend obligations owed to talent or other participants are set forth in Exhibit D and shall be satisfied by ProdCo without reducing or encumbering Amazon''s rights.', ARRAY['represents','free of liens','encumbrances','contingent compensation','profit participation','backend','Exhibit D','satisfied by ProdCo','without reducing','encumbering','Amazon''s rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Scheduled participations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Scheduling participations in Exhibit D with ProdCo satisfaction obligation is acceptable if Exhibit D is comprehensive. Legal must review scheduled obligations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is free of encumbrances. In the event any lien or encumbrance arises after the date hereof, ProdCo shall immediately notify Amazon and take all steps necessary to remove such lien or encumbrance at ProdCo''s sole cost and expense.', ARRAY['represents','free of encumbrances','lien','encumbrance','arises','after date','immediately notify','Amazon','remove','ProdCo''s cost','expense']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Future encumbrance removal obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Future encumbrance notification and removal obligation is helpful additional protection. Confirms ProdCo''s ongoing responsibility for clean title."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents the Program is free of encumbrances. With respect to underlying literary material, ProdCo has acquired all necessary rights from the author pursuant to the acquisition agreement attached as Exhibit B, which grants rights coextensive with those granted to Amazon herein.', ARRAY['represents','free of encumbrances','underlying literary material','acquired','necessary rights','author','acquisition agreement','Exhibit B','rights coextensive','granted to Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Underlying rights acquisition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reference to scheduled acquisition agreement provides transparency. Legal must verify Exhibit B agreement actually grants coextensive rights."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is not subject to any lien or encumbrance. If the Program is based on pre-existing intellectual property, ProdCo represents that it has obtained all necessary rights from the rights holder and shall provide Amazon with evidence of such rights upon request.', ARRAY['represents','not subject to','lien','encumbrance','pre-existing intellectual property','obtained','necessary rights','rights holder','provide evidence','upon request']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Pre-existing IP evidence requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Evidence-upon-request provision for pre-existing IP rights is appropriate verification mechanism. Legal should confirm evidence is obtained proactively."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To ProdCo''s knowledge, after reasonable inquiry, the Program and Materials are free of liens, encumbrances, and third-party claims.', ARRAY['to knowledge','reasonable inquiry','Program','Materials','free of liens','encumbrances','third-party claims']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier on encumbrances", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on encumbrance representation is completely unacceptable. ProdCo knows what agreements it has entered and what rights it has granted. No knowledge qualifier is appropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is free of material encumbrances. Minor encumbrances that do not significantly impair Amazon''s exploitation rights shall not constitute a breach of this representation.', ARRAY['represents','free of material encumbrances','minor encumbrances','do not significantly impair','exploitation rights','not constitute breach']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Materiality qualifier on encumbrances", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Material'' and ''minor'' qualifiers create ambiguity about what encumbrances are acceptable. Any encumbrance could affect Amazon''s rights and must be disclosed and addressed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is free of encumbrances, except for any customary industry encumbrances and except for any matters disclosed in ProdCo''s chain of title opinion, which Amazon acknowledges having received.', ARRAY['represents','free of encumbrances','except','customary industry encumbrances','except','chain of title opinion','acknowledges','received']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Chain of title opinion carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Carveout for chain of title opinion issues shifts risk of disclosed defects to Amazon. Encumbrance issues identified in opinion should be resolved, not carved out."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is currently free of encumbrances as of the Effective Date. ProdCo makes no representation regarding encumbrances that may arise after the Effective Date or during production.', ARRAY['represents','currently free','encumbrances','as of Effective Date','no representation','after Effective Date','during production']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Point-in-time only representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Point-in-time representation provides no protection against encumbrances arising during production. Representation must be continuous and cover the full term."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is free of encumbrances. However, ProdCo has entered into financing arrangements that create a security interest in ProdCo''s accounts receivable, which may include amounts payable under this Agreement. Such arrangements shall not be deemed an encumbrance on the Program itself.', ARRAY['represents','free of encumbrances','however','financing arrangements','security interest','accounts receivable','amounts payable','not deemed','encumbrance on Program']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Financing security interest carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Security interest in receivables under the Agreement could create lender claims or UCC issues. While not directly on Program, creates complications that should be addressed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that, as between ProdCo and Amazon, the Program is free of encumbrances. ProdCo''s representations hereunder are made without prejudice to any rights of third parties that may exist under applicable law.', ARRAY['represents','as between ProdCo and Amazon','free of encumbrances','without prejudice','rights of third parties','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Limited inter-party representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''As between ProdCo and Amazon'' and ''without prejudice to third parties'' creates representation that is meaningless against actual third-party claims. Representation must be absolute."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The representations and warranties in this Section shall not apply to any materials supplied by Amazon or to any materials incorporated into the Program at Amazon''s express written direction.', ARRAY['representations warranties','not apply','materials supplied by Amazon','incorporated','Program','Amazon''s express written direction']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Standard Amazon-supplied exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveout for Amazon-supplied materials and Amazon-directed inclusions. Appropriate since ProdCo cannot warrant Amazon''s own materials."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations and warranties shall not apply to: (a) materials provided by Amazon for inclusion in the Program; (b) materials incorporated at Amazon''s written request or instruction; or (c) changes made by Amazon to the Program after delivery, provided that ProdCo''s representations shall continue to apply to the underlying delivered Program.', ARRAY['representations warranties','not apply','materials provided by Amazon','incorporated','written request','instruction','changes made by Amazon','after delivery','underlying delivered Program']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Post-delivery changes carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes post-delivery changes by Amazon while preserving representation for underlying delivered Program. Clear allocation of responsibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the foregoing representations and warranties, ProdCo shall not be responsible for any claims arising solely and directly from (i) materials supplied by Amazon or its affiliates, or (ii) the manner in which Amazon exploits the Program in contexts not contemplated by this Agreement.', ARRAY['notwithstanding','not responsible','claims','solely and directly','materials supplied','Amazon','affiliates','manner','exploits','contexts not contemplated']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Amazon exploitation manner exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes exception for Amazon''s exploitation manner outside Agreement scope. ''Solely and directly'' qualifier ensures ProdCo responsibility for its own contributions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The exceptions for Amazon-supplied materials shall apply only to materials that Amazon has expressly designated in writing as being supplied for inclusion in the Program. General feedback, notes, or creative suggestions from Amazon shall not constitute ''Amazon-supplied materials'' for purposes of this exception.', ARRAY['exceptions','Amazon-supplied','expressly designated','writing','supplied for inclusion','general feedback','notes','creative suggestions','not constitute']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Narrow definition of Amazon-supplied", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Narrows Amazon-supplied exception to expressly designated materials, preventing ProdCo from claiming general Amazon feedback creates liability shift."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to Amazon-supplied materials. For the avoidance of doubt, this exception does not apply to materials that ProdCo sourced, created, or selected based on Amazon''s general creative direction or approval of ProdCo''s recommendations.', ARRAY['representations','not apply','Amazon-supplied','avoidance of doubt','not apply','ProdCo sourced','created','selected','general creative direction','approval','recommendations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "ProdCo-sourced materials remain covered", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that ProdCo-sourced materials remain covered even if Amazon provided general direction or approved recommendations. Prevents misuse of exception."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations do not cover Amazon-supplied materials. If Amazon supplies materials to ProdCo, Amazon represents to ProdCo that such materials do not, to Amazon''s knowledge, infringe third-party rights; provided that this representation shall not expand ProdCo''s indemnification rights beyond those set forth in this Agreement.', ARRAY['representations','not cover','Amazon-supplied','Amazon represents','to Amazon''s knowledge','not infringe','third-party rights','not expand','indemnification rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Limited Amazon counter-representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited Amazon representation for its supplied materials (knowledge-qualified) without expanding ProdCo''s indemnification rights. Balanced allocation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations and warranties shall not apply to materials supplied by Amazon to ProdCo pursuant to Amazon''s standard asset delivery process. Amazon shall maintain records of all materials supplied to ProdCo and shall provide copies to ProdCo upon request for documentation purposes.', ARRAY['representations warranties','not apply','materials supplied','Amazon','standard asset delivery','maintain records','provide copies','upon request','documentation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Record-keeping for supplied materials", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Record-keeping provision clarifies what materials were Amazon-supplied, reducing disputes about exception scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations shall not apply to Amazon-supplied materials or to materials incorporated at Amazon''s written direction. If ProdCo believes any Amazon-requested material may create third-party claims, ProdCo shall promptly notify Amazon and the parties shall consult regarding appropriate action.', ARRAY['representations','not apply','Amazon-supplied','written direction','ProdCo believes','may create claims','promptly notify','consult','appropriate action']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Consultation for problematic requests", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation process for potentially problematic Amazon requests is reasonable addition. Legal should confirm this doesn''t create ProdCo blocking right."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon-supplied materials exception shall apply. Additionally, ProdCo''s representations shall not apply to any third-party content that Amazon has separately cleared and for which Amazon has provided ProdCo with written confirmation of such clearance.', ARRAY['Amazon-supplied','exception','representations','not apply','third-party content','Amazon cleared','written confirmation','clearance']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Amazon-cleared content exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Extension to Amazon-cleared content with written confirmation is reasonable if Amazon is actually conducting clearances. Legal should verify clearance process."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations do not cover Amazon-supplied materials. If any claim arises from such materials, Amazon shall defend and indemnify ProdCo against such claim, provided the claim arises solely from the Amazon-supplied materials and not from ProdCo''s implementation or modification thereof.', ARRAY['representations','not cover','Amazon-supplied','claim arises','Amazon defend','indemnify','solely from','not from','ProdCo implementation','modification']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Amazon indemnity for supplied materials", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon indemnity for its supplied materials may be appropriate where Amazon is truly the source. ''Solely from'' qualifier preserves ProdCo responsibility for implementation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations do not apply to Amazon-supplied materials. For materials suggested but not supplied by Amazon, ProdCo shall conduct standard clearance procedures and representations shall apply to the cleared versions of such materials.', ARRAY['representations','not apply','Amazon-supplied','suggested but not supplied','standard clearance procedures','representations apply','cleared versions']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Suggested vs. supplied distinction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between suggested and supplied materials is appropriate. Suggested materials remain ProdCo''s clearance responsibility. Legal should confirm clarity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The exception for Amazon-supplied materials applies. However, if ProdCo had actual knowledge that any Amazon-supplied material infringed third-party rights and failed to notify Amazon prior to incorporation, ProdCo''s representations shall continue to apply to such material.', ARRAY['exception','Amazon-supplied','however','ProdCo actual knowledge','infringed','failed to notify','prior to incorporation','representations apply']::text[], '{"doc": "PSA_Fallbacks", "section": "Representations and Warranties", "note": "Known infringement carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Preserving ProdCo responsibility if it had actual knowledge of infringement in Amazon-supplied materials and failed to notify is reasonable additional protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations exclude Amazon-supplied materials. The parties shall maintain a shared log identifying all Amazon-supplied materials, and any dispute regarding whether material was Amazon-supplied shall be resolved by reference to such log.', ARRAY['representations','exclude','Amazon-supplied','maintain','shared log','identifying','dispute','resolved by reference']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Shared log for supplied materials", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Shared log mechanism provides clarity on what materials qualify for exception. Reduces disputes about exception scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to any materials regarding which Amazon provided feedback, notes, or approval, as ProdCo reasonably relied on Amazon''s input in selecting and incorporating such materials.', ARRAY['representations','not apply','materials','Amazon feedback','notes','approval','reasonably relied','Amazon''s input','selecting','incorporating']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Feedback/approval as exception trigger", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for materials Amazon approved or gave feedback on would exclude virtually all Program content. Amazon approval does not shift clearance responsibility to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to materials incorporated into the Program based on Amazon''s suggestions, preferences, or creative direction, whether written or oral.', ARRAY['representations','not apply','materials incorporated','Amazon''s suggestions','preferences','creative direction','written','oral']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Creative direction exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for materials based on Amazon''s ''suggestions, preferences, or creative direction'' would exempt most content since Amazon provides ongoing creative input. Far too broad."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Amazon-supplied exception includes any content from Amazon''s content library, licensed content available through Amazon''s production ecosystem, or any materials that ProdCo accessed through Amazon-provided credentials or systems.', ARRAY['Amazon-supplied','includes','content library','licensed content','production ecosystem','accessed','Amazon-provided credentials','systems']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Broad ecosystem exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Extending exception to anything accessed through Amazon systems would capture content ProdCo independently selects. ProdCo must clear what it chooses to use."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to materials incorporated into the Program during any production phase in which an Amazon representative was present on set or actively involved in production decisions.', ARRAY['representations','not apply','materials incorporated','production phase','Amazon representative','present','on set','actively involved','production decisions']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Amazon presence exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception based on Amazon representative presence would exclude most production content since Amazon monitors productions. Presence does not equal supply or direction."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All Amazon creative notes, approvals, and production decisions shall be deemed to constitute ''Amazon direction'' for purposes of the representation exceptions, such that ProdCo''s representations shall not apply to any element of the Program that reflects implementation of such notes or approvals.', ARRAY['Amazon creative notes','approvals','production decisions','deemed','Amazon direction','representation exceptions','not apply','reflects implementation']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Notes/approvals deemed direction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deeming all notes and approvals as ''direction'' triggering exception would gut ProdCo''s representations entirely. Standard creative oversight is not material supply or direction."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations apply only to elements of the Program that ProdCo developed independently without any input, suggestion, note, or direction from Amazon. All other elements are excluded from ProdCo''s representations.', ARRAY['representations','apply only','developed independently','without','input','suggestion','note','direction','all other elements','excluded']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Inverted exception logic", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Inverting the exception to cover only ''independently developed'' content would exclude virtually all Program content. Collaborative production doesn''t shift clearance responsibility."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants, without qualification, that the Program and Materials are original, do not infringe any third-party rights, and are free from all encumbrances. For the avoidance of doubt, these representations are not qualified by any ''knowledge'' or ''awareness'' standard.', ARRAY['represents warrants','without qualification','original','not infringe','third-party rights','free from encumbrances','not qualified','knowledge','awareness standard']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Explicit no-knowledge-qualifier statement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly states representations are unqualified, preventing any argument that knowledge standards apply. Clear and unambiguous."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations and warranties in this Agreement are absolute and are not subject to any ''to the best of ProdCo''s knowledge,'' ''to ProdCo''s knowledge,'' ''so far as ProdCo is aware,'' or similar knowledge-based qualification.', ARRAY['representations warranties','absolute','not subject to','to the best of knowledge','to knowledge','so far as aware','knowledge-based qualification']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Enumerated prohibited qualifiers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific prohibited qualifier formulations, eliminating ambiguity about which qualifiers are unacceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All representations and warranties made by ProdCo are made absolutely and without any knowledge qualification. ProdCo acknowledges that Amazon is relying on these representations in entering into this Agreement and that any knowledge qualification would be material to Amazon.', ARRAY['representations warranties','absolutely','without knowledge qualification','acknowledges','Amazon relying','entering into','knowledge qualification','material']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Reliance acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes ProdCo''s acknowledgment of Amazon''s reliance, reinforcing that knowledge qualifiers are unacceptable and that their absence is bargained-for."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights. This representation is not qualified by any standard relating to ProdCo''s knowledge, belief, awareness, inquiry, or investigation. ProdCo assumes full responsibility for the accuracy of this representation regardless of what ProdCo knew or could have known.', ARRAY['represents warrants','not infringe','not qualified','knowledge','belief','awareness','inquiry','investigation','full responsibility','accuracy','regardless','knew','could have known']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Comprehensive qualifier rejection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers full range of potential qualifiers (knowledge, belief, awareness, inquiry, investigation) and explicitly assumes responsibility regardless of what ProdCo knew."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations are made without knowledge qualifiers. ProdCo shall not be entitled to assert as a defense to any breach of representation claim that ProdCo did not know or could not reasonably have known of the facts giving rise to such breach.', ARRAY['representations','without knowledge qualifiers','not entitled','assert','defense','breach','claim','did not know','could not have known','facts','breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Defense waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Waives knowledge-based defenses to breach claims, ensuring representations are enforceable regardless of ProdCo''s actual knowledge."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The representations in this Section are made as absolute representations, not as representations of belief or knowledge. Any provision of this Agreement that might be interpreted as implying a knowledge qualification shall be construed to exclude such qualification.', ARRAY['representations','absolute','not representations of belief','knowledge','provision','interpreted','implying','knowledge qualification','construed','exclude']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Construction against qualifiers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Construction clause prevents interpretation that would imply knowledge qualifiers. Belt-and-suspenders protection against qualified readings."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo makes each representation and warranty herein absolutely and unconditionally. The parties expressly agree that no representation or warranty shall be subject to any knowledge, awareness, diligence, or investigation qualification, and any such qualification is hereby deleted if inadvertently included.', ARRAY['representation warranty','absolutely','unconditionally','expressly agree','not subject to','knowledge','awareness','diligence','investigation','deleted','inadvertently included']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Auto-deletion of inadvertent qualifiers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Auto-deletion provision addresses possibility that qualifiers appear elsewhere in Agreement and ensures they are ineffective."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are made without knowledge qualification. Notwithstanding the foregoing, with respect to representations regarding conduct of third parties not under ProdCo''s control (e.g., predecessor owners of underlying rights), such representations may be qualified by ''to ProdCo''s knowledge after reasonable inquiry.''', ARRAY['representations','without knowledge qualification','notwithstanding','third parties','not under control','predecessor owners','underlying rights','qualified','to knowledge','reasonable inquiry']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Third-party conduct exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited exception for third-party conduct (predecessor chain of title) may be acceptable since ProdCo cannot absolutely warrant others'' actions. Legal should confirm scope is narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are absolute and unqualified. ProdCo has conducted due diligence sufficient to make such representations without knowledge qualifiers, including review of all underlying agreements, copyright registrations, and chain of title documentation.', ARRAY['representations','absolute','unqualified','conducted due diligence','sufficient','without knowledge qualifiers','underlying agreements','copyright registrations','chain of title']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Diligence statement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Statement regarding conducted diligence supports absolute representations without creating qualification. Confirms basis for unqualified representations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Representations are made without knowledge qualification. If any representation proves to be inaccurate despite ProdCo''s good faith belief at the time of making, ProdCo shall remain fully liable for breach; provided that ProdCo''s good faith may be considered in determining appropriate remedies.', ARRAY['representations','without knowledge qualification','inaccurate','despite','good faith belief','fully liable','breach','good faith','considered','determining remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Good faith in remedy determination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Preserving full liability while allowing good faith consideration in remedies is pragmatic. Legal should confirm this doesn''t limit damages or indemnification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are absolute. ProdCo shall maintain errors and omissions insurance covering claims arising from breach of representations regardless of ProdCo''s knowledge at the time of making such representations.', ARRAY['representations','absolute','maintain','E&O insurance','covering claims','breach of representations','regardless','knowledge','time of making']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "E&O coverage for unknown breaches", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "E&O insurance covering unknown-at-time-of-making breaches provides additional protection layer. Confirms financial backing for absolute representations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are not knowledge-qualified. In the event of a breach, ProdCo''s lack of knowledge shall not excuse the breach, but may be relevant to determining whether such breach was willful or negligent for purposes of any punitive or enhanced damages analysis.', ARRAY['representations','not knowledge-qualified','breach','lack of knowledge','not excuse','may be relevant','willful','negligent','punitive','enhanced damages']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge relevant to punitive damages", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Allowing knowledge relevance only for punitive/enhanced damages analysis preserves core representation while addressing equity concerns. Legal should confirm this is acceptable scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No knowledge qualification applies to ProdCo''s representations. If ProdCo discovers after the date hereof any fact that would constitute a breach of representation, ProdCo shall immediately notify Amazon and cooperate in addressing the issue, which prompt notification may be considered in evaluating ProdCo''s good faith.', ARRAY['no knowledge qualification','representations','discovers','after date','breach of representation','immediately notify','cooperate','addressing issue','prompt notification','evaluating good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Notification for discovered issues", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-signing notification obligation for discovered issues is reasonable procedural addition. Good faith consideration doesn''t reduce liability."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the best of ProdCo''s knowledge after reasonable inquiry, the Program does not infringe any intellectual property rights, does not defame any person, and does not violate any right of privacy or publicity.', ARRAY['to the best of knowledge','reasonable inquiry','Program','not infringe','intellectual property','defame','privacy','publicity']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Standard knowledge qualifier", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "This is exactly the knowledge qualifier that must be rejected. ''To the best of ProdCo''s knowledge after reasonable inquiry'' limits representation to what ProdCo knows, not to actual facts."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that, so far as ProdCo is aware having made all reasonable inquiries, the Program is original and does not infringe any third-party rights.', ARRAY['represents','so far as aware','reasonable inquiries','Program','original','not infringe','third-party rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Awareness qualifier", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''So far as ProdCo is aware'' is a knowledge qualifier that must be rejected. This limits representation to ProdCo''s subjective awareness."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that ProdCo has no knowledge of any facts that would indicate that the Program infringes any third-party rights or that any claims have been or are likely to be asserted.', ARRAY['represents warrants','no knowledge','facts','indicate','Program infringes','third-party rights','claims','asserted','likely']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "No-knowledge-of-facts formulation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''No knowledge of any facts'' is a knowledge-qualified representation dressed in different language. This is not a representation that the Program doesn''t infringe."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that it believes the Program is original and non-infringing based on ProdCo''s review of available information and consultation with legal counsel.', ARRAY['represents','believes','Program','original','non-infringing','based on','review','available information','consultation','legal counsel']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Belief-based representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Believes'' is a subjective qualifier equivalent to a knowledge qualifier. ProdCo must represent facts, not beliefs about facts."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that ProdCo has not received any notice or claim asserting that the Program infringes any third-party rights, and ProdCo is not aware of any basis for such a claim.', ARRAY['represents','not received','notice','claim','asserting','Program infringes','third-party rights','not aware','basis','claim']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "No-notice representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Representing only that no notice has been received is not a representation of non-infringement. Many infringements exist without prior notice or claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that, based on the clearance procedures conducted by ProdCo, the Program does not, in ProdCo''s reasonable professional judgment, infringe any third-party rights.', ARRAY['represents','based on','clearance procedures','Program','reasonable professional judgment','not infringe','third-party rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Professional judgment qualifier", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable professional judgment'' is a subjective standard equivalent to a knowledge qualifier. ProdCo must represent objective facts, not professional opinions."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents, warrants and covenants that it shall comply with all applicable laws, statutes, regulations and orders, including without limitation export control laws (including ITAR and EAR), economic sanctions laws and regulations administered by OFAC, anti-boycott laws, anti-corruption laws (including the FCPA and UK Bribery Act), and laws relating to the facilitation of tax evasion.', ARRAY['comply','applicable laws','statutes','regulations','orders','export control','ITAR','EAR','sanctions','OFAC','anti-boycott','anti-corruption','FCPA','UK Bribery Act','tax evasion','facilitation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Comprehensive control laws compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive compliance representation covering all major control laws categories. Enumeration of specific laws provides clarity while catch-all ensures complete coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all applicable economic sanctions and export control laws, including those administered by the U.S. Department of the Treasury''s Office of Foreign Assets Control (OFAC), the U.S. Department of Commerce''s Bureau of Industry and Security (BIS), and analogous authorities in other jurisdictions where the Program will be produced or exploited.', ARRAY['comply','economic sanctions','export control','OFAC','Treasury','BIS','Commerce','analogous authorities','jurisdictions','produced','exploited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Multi-agency compliance with jurisdictional scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Identifies specific U.S. agencies and extends to analogous authorities in production/exploitation territories. Appropriate for international productions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (a) neither ProdCo nor any of its owners, directors, officers, employees or agents is a Sanctioned Person; (b) ProdCo shall not engage in any transaction or activity that would cause Amazon to violate any sanctions or export control laws; and (c) ProdCo shall immediately notify Amazon if any of the foregoing representations ceases to be accurate.', ARRAY['represents warrants','owners','directors','officers','employees','agents','Sanctioned Person','not engage','transaction','activity','cause Amazon','violate','sanctions','export control','immediately notify','ceases accurate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Sanctioned Person representation with notification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers ProdCo and its personnel, includes commitment not to cause Amazon violations, and requires immediate notification of changes. Comprehensive sanctions protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all anti-boycott laws and regulations, including Section 999 of the Internal Revenue Code and the Export Administration Regulations. ProdCo shall not participate in or cooperate with any international boycott not sanctioned by the United States, and shall report any boycott-related requests received in connection with the Program.', ARRAY['comply','anti-boycott','Section 999','Internal Revenue Code','Export Administration Regulations','not participate','cooperate','international boycott','not sanctioned','United States','report','boycott-related requests']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Anti-boycott specific compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific anti-boycott compliance with reporting requirement. Important for productions involving Middle East locations or talent."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not, directly or indirectly, offer, pay, promise, or authorize payment of anything of value to any government official, political party, or candidate for public office for the purpose of influencing any act or decision, or securing any improper advantage. ProdCo shall comply with the U.S. Foreign Corrupt Practices Act and the UK Bribery Act 2010.', ARRAY['not offer','pay','promise','authorize payment','anything of value','government official','political party','candidate','influencing','improper advantage','FCPA','UK Bribery Act 2010']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Anti-corruption compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Substantive anti-bribery commitment with reference to key anti-corruption laws. Important for international productions involving government permits or incentives."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that it has not engaged, and shall not engage, in any conduct that would constitute an offence under the UK Criminal Finances Act 2017 or any analogous law relating to the facilitation of tax evasion. ProdCo has reasonable prevention procedures in place to prevent any associated person from facilitating tax evasion.', ARRAY['represents warrants','not engaged','shall not engage','UK Criminal Finances Act 2017','analogous law','facilitation','tax evasion','reasonable prevention procedures','associated person']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Tax evasion facilitation compliance", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-specific tax evasion facilitation compliance including procedural requirement. Essential for UK productions or UK-headquartered ProdCos."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain and enforce policies and procedures designed to ensure compliance with all applicable sanctions, export control, anti-corruption, anti-boycott, and anti-money laundering laws. ProdCo shall provide Amazon with copies of such policies upon request and shall permit Amazon to audit ProdCo''s compliance upon reasonable notice.', ARRAY['maintain','enforce','policies','procedures','compliance','sanctions','export control','anti-corruption','anti-boycott','anti-money laundering','provide copies','upon request','audit','reasonable notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Compliance program with audit right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Requires compliance program and grants Amazon audit rights. Provides ongoing verification mechanism beyond representations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable sanctions, export control, and anti-corruption laws. ProdCo represents that it has conducted appropriate due diligence on its supply chain and personnel, but acknowledges that it cannot guarantee compliance by all third parties engaged in connection with the Program.', ARRAY['comply','sanctions','export control','anti-corruption','due diligence','supply chain','personnel','acknowledges','cannot guarantee','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Third-party compliance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment regarding third-party compliance may be reasonable if ProdCo''s due diligence obligations are clear. Legal should confirm indemnity covers third-party violations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable control laws. If ProdCo becomes aware of any potential violation, ProdCo shall immediately notify Amazon and cooperate with any investigation. Amazon shall have the right to suspend payments pending resolution of any compliance concern.', ARRAY['comply','control laws','becomes aware','potential violation','immediately notify','cooperate','investigation','suspend payments','pending resolution','compliance concern']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Notification with payment suspension", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notification and cooperation obligations with payment suspension right strengthens Amazon''s enforcement ability. Standard compliance program element."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with OFAC sanctions regulations. For cast and crew engaged from jurisdictions subject to comprehensive sanctions programs (if any such engagement is permitted), ProdCo shall obtain specific OFAC licenses and shall provide Amazon with copies of such licenses prior to commencing services.', ARRAY['comply','OFAC','sanctions','cast','crew','comprehensive sanctions','permitted','obtain','specific OFAC licenses','copies','prior to commencing']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Sanctions license documentation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Addresses rare scenario where licensed activity in sanctioned jurisdictions may be permitted. License documentation requirement is essential. Legal must review any such engagement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable sanctions and export control laws. ProdCo acknowledges that certain technical data or technology used in production may be subject to export controls and shall implement appropriate controls to prevent unauthorized transfers.', ARRAY['comply','sanctions','export control','technical data','technology','production','subject to','export controls','implement','appropriate controls','prevent','unauthorized transfers']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Technical data export controls", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledges export control applicability to production technology (VFX, proprietary systems). Implementation requirement is appropriate. Legal should confirm scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents compliance with all control laws. ProdCo shall include equivalent compliance representations and covenants in all agreements with production vendors, financiers, and other third parties, and shall flow down Amazon''s compliance requirements to such parties.', ARRAY['represents','compliance','control laws','include','equivalent','representations','covenants','production vendors','financiers','third parties','flow down','Amazon''s requirements']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Flow-down to third parties", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Flow-down requirement extends compliance obligations through the production chain. Important for managing indirect compliance risk."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable sanctions, export control, anti-corruption and tax evasion facilitation laws. The parties acknowledge that applicable laws vary by jurisdiction, and ProdCo shall comply with the laws of each jurisdiction in which production activities occur and the laws applicable to Amazon.', ARRAY['comply','sanctions','export control','anti-corruption','tax evasion','laws vary','jurisdiction','comply','each jurisdiction','production activities','laws applicable','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Multi-jurisdiction compliance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledges jurisdictional variation while requiring compliance in all production jurisdictions and with laws applicable to Amazon. Appropriate for international productions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to comply with applicable sanctions and export control laws. ProdCo shall not be liable for inadvertent violations resulting from incomplete or incorrect information provided by third parties.', ARRAY['reasonable efforts','comply','sanctions','export control','not liable','inadvertent violations','incomplete','incorrect information','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Reasonable efforts with liability limitation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' is inadequate for control laws compliance\u2014violations can result in severe penalties for Amazon. Liability limitation for ''inadvertent violations'' is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with sanctions laws to the extent ProdCo has actual knowledge of applicable restrictions. ProdCo shall not be required to conduct independent screening or verification of personnel or vendors.', ARRAY['comply','sanctions','actual knowledge','applicable restrictions','not required','conduct','independent screening','verification','personnel','vendors']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Knowledge qualifier with no screening", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on sanctions compliance and elimination of screening requirement creates massive compliance gap. Sanctions compliance requires affirmative diligence, not just responding to known issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with U.S. sanctions and export control laws. ProdCo makes no representation regarding compliance with non-U.S. sanctions regimes, including EU, UK, or UN sanctions, which shall be Amazon''s responsibility to assess.', ARRAY['comply','U.S. sanctions','export control','no representation','non-U.S.','EU','UK','UN sanctions','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "U.S.-only compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting compliance to U.S. sanctions only creates exposure under EU, UK, and other regimes that may apply to productions. ProdCo must comply with all applicable sanctions regimes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with applicable sanctions laws. If compliance would materially increase production costs or delay the production schedule, ProdCo may request a waiver from Amazon, and Amazon shall consider such request in good faith.', ARRAY['comply','sanctions','materially increase','production costs','delay','production schedule','request waiver','Amazon','consider','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Cost/delay waiver provision", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Sanctions compliance cannot be waived due to cost or schedule impact. Waiver request mechanism suggests compliance is optional, which is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with applicable sanctions laws currently in effect. ProdCo shall not be responsible for compliance with sanctions laws enacted or modified after the Effective Date unless Amazon provides written notice of such new requirements and adequate time for implementation.', ARRAY['comply','sanctions','currently in effect','not responsible','enacted','modified','after Effective Date','written notice','new requirements','adequate time','implementation']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Point-in-time compliance only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting compliance to laws ''currently in effect'' creates ongoing risk as sanctions regimes change frequently. ProdCo must comply with laws as they exist throughout production."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall comply with applicable sanctions and export control laws. Neither party makes any representation to the other regarding the other party''s compliance, and each party shall be solely responsible for its own compliance.', ARRAY['each party','comply','sanctions','export control','neither party','representation','other party''s compliance','solely responsible','own compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "No cross-representation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Amazon needs ProdCo''s representations regarding ProdCo''s compliance because ProdCo''s violations can expose Amazon. ''Each party solely responsible'' doesn''t address vicarious liability risk."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with sanctions laws. In the event of any violation by ProdCo, Amazon''s sole remedy shall be termination of this Agreement. ProdCo shall not be liable for any penalties, fines, or other sanctions imposed on Amazon as a result of ProdCo''s non-compliance.', ARRAY['comply','sanctions','violation','Amazon''s sole remedy','termination','not liable','penalties','fines','sanctions imposed','Amazon','non-compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Termination as sole remedy", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination as sole remedy with no liability for penalties is completely unacceptable. ProdCo violations could result in massive fines and reputational harm to Amazon for which ProdCo must be liable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all Amazon policies and guidelines provided to ProdCo, including without limitation the policies set forth in the Amazon Production Kickoff Packet, Amazon''s Content Policy, Workplace Conduct Policy, Safety Guidelines, and any other policies communicated by Amazon from time to time.', ARRAY['comply','Amazon policies','guidelines','Production Kickoff Packet','Content Policy','Workplace Conduct Policy','Safety Guidelines','communicated','from time to time']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Standard Amazon policies compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard requirement to comply with Amazon policies including kickoff packet. ''From time to time'' language allows for policy updates during production."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges receipt of the Amazon Production Kickoff Packet and agrees to comply with all policies, procedures, and guidelines contained therein. ProdCo shall ensure that all cast, crew, and production personnel review and acknowledge applicable policies prior to commencing services.', ARRAY['acknowledges receipt','Production Kickoff Packet','comply','policies','procedures','guidelines','ensure','cast','crew','production personnel','review','acknowledge','prior to commencing']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Receipt acknowledgment with flow-through", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes acknowledgment of receipt and requirement to flow through to personnel with documented acknowledgment. Creates accountability chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon''s policies as updated from time to time. Amazon shall provide ProdCo with reasonable notice of material policy changes; provided that compliance with updated policies shall be required regardless of whether notice was provided, and failure to receive notice shall not excuse non-compliance.', ARRAY['comply','Amazon''s policies','updated','from time to time','reasonable notice','material changes','compliance required','regardless','notice','failure','not excuse','non-compliance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Policy updates with notice", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses policy updates with notice commitment while preserving compliance requirement regardless of notice. Balances operational fairness with compliance necessity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon''s production policies, including policies relating to set safety, workplace conduct, anti-harassment, environmental sustainability, data security, and content standards. ProdCo shall designate a compliance coordinator responsible for ensuring policy compliance and shall provide Amazon with such coordinator''s contact information.', ARRAY['comply','production policies','set safety','workplace conduct','anti-harassment','environmental sustainability','data security','content standards','designate','compliance coordinator','contact information']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Compliance coordinator requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates policy categories and requires designated compliance coordinator. Creates single point of contact for policy compliance matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all Amazon policies and shall incorporate policy compliance requirements into all agreements with cast and crew. If any policy requirement conflicts with applicable law or collective bargaining agreements, ProdCo shall immediately notify Amazon and the parties shall work together to resolve such conflict.', ARRAY['comply','Amazon policies','incorporate','policy compliance','agreements','cast','crew','conflicts','applicable law','collective bargaining','immediately notify','work together','resolve conflict']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "CBA conflict resolution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses potential conflicts with law or CBAs through notification and resolution process. Practical approach to real-world compliance challenges."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall adhere to Amazon''s production policies. In the event of any violation, ProdCo shall immediately report such violation to Amazon, take corrective action, and cooperate with any Amazon investigation. Amazon may, in its sole discretion, require removal of any personnel involved in policy violations.', ARRAY['adhere','production policies','violation','immediately report','corrective action','cooperate','investigation','sole discretion','require removal','personnel','policy violations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Violation reporting and personnel removal", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes violation reporting, corrective action, and Amazon''s right to require personnel removal. Important for workplace safety and conduct violations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies available at [Amazon policy portal URL] or as otherwise communicated. ProdCo is responsible for regularly checking for policy updates and ensuring production compliance with current policies. ProdCo''s failure to check for updates shall not excuse non-compliance.', ARRAY['comply','Amazon policies','policy portal','communicated','responsible','regularly checking','updates','production compliance','current policies','failure to check','not excuse','non-compliance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Portal-based policies with checking responsibility", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Places responsibility on ProdCo to monitor policy portal for updates. Practical for dynamic policy environments."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies provided in the Kickoff Packet. Material changes to policies after the Effective Date shall be provided to ProdCo in writing at least ten (10) business days before ProdCo is required to comply, except for changes required by law or safety concerns which shall be effective immediately.', ARRAY['comply','Amazon policies','Kickoff Packet','material changes','after Effective Date','writing','ten business days','before required','except','law','safety','effective immediately']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Notice period for policy changes", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ten-day notice for material policy changes is reasonable operational accommodation with appropriate carveouts for law and safety. Legal should confirm timing is workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon production policies. If any policy change would require material modification to the approved production budget or schedule, Amazon shall consult with ProdCo regarding implementation and shall consider in good faith any impact on ProdCo''s ability to deliver the Program.', ARRAY['comply','production policies','policy change','material modification','budget','schedule','consult','implementation','consider','good faith','impact','ability to deliver']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Budget/schedule impact consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation regarding budget/schedule impact of policy changes is reasonable operational accommodation that doesn''t eliminate compliance requirement. Legal should confirm compliance remains mandatory."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies. Amazon acknowledges that certain policies may need to be adapted for local production conditions, and Amazon agrees to work with ProdCo in good faith to develop locally-appropriate compliance approaches that achieve the policy objectives.', ARRAY['comply','Amazon policies','acknowledges','adapted','local production conditions','work','good faith','locally-appropriate','compliance approaches','achieve','policy objectives']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Local adaptation acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment of local adaptation needs for international productions is practical. ''Achieve policy objectives'' preserves substantive compliance. Legal should confirm flexibility is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon''s Kickoff Packet policies. ProdCo may request clarification of any policy requirement, and Amazon shall respond to such requests within five (5) business days. ProdCo''s good faith compliance with Amazon''s clarification shall not constitute a breach if the clarification later proves to be incorrect.', ARRAY['comply','Kickoff Packet','request clarification','policy requirement','respond','five business days','good faith compliance','clarification','not constitute breach','later proves incorrect']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Clarification with safe harbor", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification mechanism with safe harbor for good faith reliance is reasonable. Protects ProdCo from liability for following Amazon''s own interpretation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies. If ProdCo believes any policy requirement is impractical or inappropriate for the specific production context, ProdCo may submit a variance request to Amazon in writing. Amazon shall respond within five (5) business days and may grant or deny the variance in its sole discretion.', ARRAY['comply','Amazon policies','believes','impractical','inappropriate','production context','variance request','writing','respond','five business days','grant','deny','sole discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Variance request mechanism", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Variance request mechanism with Amazon sole discretion is reasonable flexibility while preserving Amazon control. Legal should confirm process is operationally appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon production policies. Amazon represents that the policies in the Kickoff Packet are consistent with industry-standard production practices. If any policy materially exceeds industry standards, Amazon shall provide additional budget allowance for compliance costs upon ProdCo''s reasonable request.', ARRAY['comply','production policies','represents','Kickoff Packet','consistent','industry-standard','materially exceeds','industry standards','additional budget allowance','compliance costs','reasonable request']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Industry standard with budget adjustment", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Budget allowance for policies exceeding industry standards is commercial term. Business Affairs should assess whether this is appropriate for the specific production."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use commercially reasonable efforts to comply with Amazon policies to the extent such compliance does not unreasonably interfere with production operations or impose material additional costs.', ARRAY['commercially reasonable efforts','comply','Amazon policies','extent','does not unreasonably interfere','production operations','impose','material additional costs']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Reasonable efforts with interference/cost carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Commercially reasonable efforts'' with interference and cost carveouts effectively makes policy compliance optional. Amazon policies must be mandatory, not aspirational."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies as set forth in the Kickoff Packet provided at signing. Amazon may not modify, add to, or expand such policies during production without ProdCo''s written consent.', ARRAY['comply','Amazon policies','Kickoff Packet','at signing','may not modify','add to','expand','during production','without','written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Policy freeze during production", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Freezing policies at signing prevents Amazon from updating policies for safety, legal, or operational reasons during production. Amazon must retain ability to update policies."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies that have been expressly identified in the Kickoff Packet. ProdCo shall not be bound by any policy not specifically enumerated in the Kickoff Packet or by any policy communicated only verbally.', ARRAY['comply','Amazon policies','expressly identified','Kickoff Packet','not bound','not specifically enumerated','communicated only verbally']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Limited to enumerated policies only", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Limiting compliance to enumerated policies creates gaps for new policies or policies communicated during production. Amazon needs flexibility to require compliance with evolving policies."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies. Any policy violation shall be addressed through a progressive discipline process, and ProdCo shall not be in breach unless a violation continues after three (3) written warnings and a thirty (30) day cure period.', ARRAY['comply','Amazon policies','policy violation','progressive discipline','not in breach','continues','three written warnings','thirty day cure period']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Progressive discipline for violations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Progressive discipline with three warnings and 30-day cure is completely inappropriate for safety or conduct violations. Many violations require immediate action, not extended cure periods."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies to the extent such policies are consistent with applicable collective bargaining agreements. In the event of any conflict between Amazon policy and CBA requirements, the CBA shall control.', ARRAY['comply','Amazon policies','extent','consistent','collective bargaining agreements','conflict','CBA requirements','CBA shall control']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "CBA override of Amazon policies", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Blanket CBA override of Amazon policies is too broad. While genuine conflicts must be addressed, Amazon policies generally operate alongside CBA requirements. Conflicts should be resolved case-by-case."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees to review Amazon''s policies and implement those that ProdCo determines, in its reasonable discretion, are appropriate for the production. ProdCo''s good faith determination of appropriateness shall be binding.', ARRAY['review','Amazon''s policies','implement','ProdCo determines','reasonable discretion','appropriate','production','good faith determination','binding']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "ProdCo discretion on which policies to follow", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo discretion over which policies to implement completely undermines compliance framework. Amazon''s policies must be mandatory, not subject to ProdCo''s selection."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable laws. Amazon shall comply with all applicable laws in its exploitation of the Program. For the avoidance of doubt, ProdCo''s compliance obligations are independent of and not contingent upon Amazon''s compliance.', ARRAY['ProdCo','comply','applicable laws','Amazon','comply','exploitation','Program','ProdCo''s obligations','independent','not contingent','Amazon''s compliance']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Parallel but independent compliance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Parallel compliance obligations that are clearly independent is acceptable structure. Key is that ProdCo''s obligations don''t depend on Amazon''s performance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party shall comply with all applicable laws in performing its obligations under this Agreement. ProdCo''s compliance obligations include the specific matters set forth in this Section. Amazon''s compliance obligations shall be determined by laws applicable to its business operations.', ARRAY['each party','comply','applicable laws','performing obligations','ProdCo''s compliance','specific matters','this Section','Amazon''s compliance','laws applicable','business operations']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Mutual with differentiated scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Mutual compliance with differentiated scope is acceptable. ProdCo''s specific obligations remain enumerated while Amazon''s are general law compliance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable laws and Amazon policies. Amazon represents that it has implemented reasonable compliance measures regarding its own operations. Neither party shall knowingly take any action that would cause the other party to violate applicable law.', ARRAY['ProdCo comply','applicable laws','Amazon policies','Amazon represents','reasonable compliance measures','own operations','neither party','knowingly','cause other party','violate']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon compliance measures representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon representation of ''reasonable compliance measures'' is limited commitment that may be acceptable. ''Neither party shall knowingly cause violation'' is reasonable mutual covenant."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply materially with all applicable laws and Amazon policies. For purposes of this Agreement, ''material compliance'' means compliance with all significant legal requirements, recognizing that minor, inadvertent deviations that do not affect Amazon''s rights or expose Amazon to liability shall not constitute a breach.', ARRAY['comply materially','applicable laws','Amazon policies','material compliance','significant legal requirements','minor inadvertent deviations','not affect','Amazon''s rights','not expose','liability','not constitute breach']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Material compliance standard", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Material compliance'' with defined parameters may be acceptable for administrative/technical requirements. Legal should confirm this doesn''t apply to control laws compliance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party shall comply with applicable laws. If Amazon requests that ProdCo implement compliance measures beyond those required by law, Amazon shall reimburse ProdCo''s reasonable incremental costs of such additional measures, provided ProdCo obtains Amazon''s prior approval of such costs.', ARRAY['each party','comply','applicable laws','Amazon requests','compliance measures','beyond required by law','reimburse','reasonable incremental costs','additional measures','prior approval']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Cost sharing for above-law measures", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cost sharing for compliance measures exceeding legal requirements is commercial negotiation point. Business Affairs should assess whether incremental costs are significant."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall implement compliance measures regarding sanctions, export control, anti-corruption, and policy compliance. Amazon shall provide ProdCo with guidance regarding compliance expectations, and Amazon''s compliance team shall be available to consult with ProdCo on compliance matters upon reasonable request.', ARRAY['implement','compliance measures','sanctions','export control','anti-corruption','policy','Amazon provide','guidance','compliance expectations','compliance team','available','consult','reasonable request']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon compliance support", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon commitment to provide guidance and consultation on compliance is helpful support that doesn''t shift responsibility. May improve actual compliance outcomes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all control laws. Amazon and ProdCo shall cooperate in good faith on compliance matters, including sharing relevant information (subject to confidentiality protections) and coordinating compliance-related communications to governmental authorities.', ARRAY['comply','control laws','Amazon','ProdCo','cooperate','good faith','compliance matters','sharing information','confidentiality','coordinating','communications','governmental authorities']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Compliance cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cooperation on compliance matters and coordinated government communications is reasonable mutual commitment that supports overall compliance objectives."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party represents that it has implemented compliance programs appropriate to its size and operations. ProdCo''s compliance program shall address the specific areas enumerated in this Agreement. Upon reasonable request, each party shall provide the other with a summary of its compliance program (subject to confidentiality).', ARRAY['each party represents','compliance programs','appropriate','size','operations','ProdCo''s compliance','specific areas','enumerated','upon request','provide','summary','confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Mutual compliance program representations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual compliance program representations with summary sharing is reasonable transparency. ''Appropriate to size and operations'' provides flexibility without eliminating requirement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all applicable laws. Amazon shall comply with all applicable laws on an equivalent basis, and Amazon''s compliance obligations shall be no less stringent than those imposed on ProdCo.', ARRAY['ProdCo comply','applicable laws','Amazon comply','equivalent basis','Amazon''s compliance','no less stringent','imposed on ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Forced equivalence of compliance", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forcing Amazon to accept ''equivalent'' or ''no less stringent'' compliance obligations ignores legitimate asymmetry. ProdCo has specific production compliance obligations that don''t translate to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall comply with applicable laws. Neither party shall be in breach of its compliance obligations unless the breach is material, willful, and continues uncured for sixty (60) days after written notice from the other party.', ARRAY['each party','comply','applicable laws','neither party','breach','unless','material','willful','continues uncured','sixty days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Qualified breach standard for compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Material, willful, and 60-day cure standard for compliance breaches is wholly inappropriate for control laws violations. Many violations cannot be cured and require immediate consequences."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s compliance obligations are mutual with Amazon''s obligations. If Amazon is found to be in violation of any law, ProdCo''s corresponding compliance obligations shall be suspended until Amazon cures its violation.', ARRAY['ProdCo''s compliance','mutual','Amazon''s obligations','Amazon violation','any law','ProdCo''s obligations','suspended','until Amazon cures']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Compliance conditioned on Amazon compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning ProdCo''s compliance on Amazon''s compliance is completely unacceptable. Compliance obligations must be independent, not subject to cross-suspension."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall use reasonable efforts to comply with applicable laws. Neither party guarantees compliance, and each party shall be liable to the other only for compliance failures resulting from gross negligence or willful misconduct.', ARRAY['each party','reasonable efforts','comply','applicable laws','neither party guarantees','liable','only','gross negligence','willful misconduct']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Reasonable efforts with gross negligence limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' with gross negligence/willful misconduct liability limitation is completely inadequate for compliance obligations. Compliance must be absolute, not effort-based."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Both parties shall comply with applicable laws. The parties agree that any compliance-related liability shall be shared equally between them, regardless of which party''s actions gave rise to such liability.', ARRAY['both parties','comply','applicable laws','compliance-related liability','shared equally','regardless','which party''s actions','gave rise']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Equal liability sharing", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Equal liability sharing regardless of fault completely undermines compliance incentives. Each party must bear liability for its own compliance failures."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with applicable laws. Amazon represents and warrants that its operations comply with all applicable laws, and Amazon shall indemnify ProdCo against any losses arising from Amazon''s failure to so comply.', ARRAY['ProdCo comply','applicable laws','Amazon represents warrants','operations comply','all applicable laws','Amazon indemnify','ProdCo','losses','Amazon''s failure']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Amazon compliance representation and indemnity", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Expansive Amazon compliance representation with ProdCo indemnification is inappropriate. Amazon provides limited indemnification per standard scope, not broad compliance indemnity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Compliance obligations are mutual. Amazon shall provide ProdCo with detailed evidence of Amazon''s compliance with all applicable laws upon ProdCo''s request, including internal audit reports, compliance certifications, and governmental correspondence.', ARRAY['compliance obligations','mutual','Amazon provide','detailed evidence','compliance','applicable laws','upon request','internal audit reports','certifications','governmental correspondence']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon compliance disclosure to ProdCo", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring Amazon to disclose internal audit reports, certifications, and government correspondence to ProdCo is completely inappropriate. Amazon''s internal compliance is confidential."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has the right and power to enter into this Agreement and to perform its obligations hereunder. This representation shall not be construed to expand Amazon''s obligations beyond those expressly set forth in this Agreement.', ARRAY['Amazon represents','right','power','enter into','Agreement','perform obligations','not construed','expand','obligations','beyond','expressly set forth']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Limited Amazon authority representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited Amazon representation of authority to contract is acceptable if scope is properly constrained. Clarification that it doesn''t expand obligations is important."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that: (a) Amazon is a duly organized entity in good standing; (b) Amazon has the corporate power and authority to execute and perform this Agreement; and (c) this Agreement constitutes a legal, valid and binding obligation of Amazon. These representations do not address any matters other than Amazon''s capacity to contract.', ARRAY['Amazon represents','duly organized','good standing','corporate power','authority','execute','perform','legal','valid','binding','obligation','do not address','matters','other than','capacity to contract']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Corporate capacity representation only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Corporate capacity representation limited to contracting authority is standard commercial language. Express limitation to ''capacity to contract'' prevents expansion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has the right and authority to enter into this Agreement. Amazon further represents that its execution and performance of this Agreement will not conflict with any other agreement to which Amazon is a party, provided that this representation is limited to agreements directly relating to the Program.', ARRAY['Amazon represents','right','authority','enter into','execution','performance','not conflict','other agreement','party','provided','limited','agreements','directly relating','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "No-conflict representation (limited)", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "No-conflict representation limited to Program-related agreements is more specific but still narrow. Legal should confirm this is operationally appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has all necessary rights and approvals to commission the Program and to grant ProdCo the rights to provide services hereunder. Amazon represents that the rights granted to ProdCo herein do not conflict with any exclusive rights previously granted by Amazon to third parties regarding the Program.', ARRAY['Amazon represents','necessary rights','approvals','commission','Program','grant ProdCo','rights','services','not conflict','exclusive rights','previously granted','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon rights to commission representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Representation that Amazon has rights to commission the Program and hasn''t granted conflicting exclusive rights is reasonable and provides ProdCo assurance of Amazon''s authority."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has authority to enter into this Agreement. If the Program is based on underlying intellectual property, Amazon represents that it has obtained or will obtain all rights necessary for ProdCo to perform services in connection with such intellectual property.', ARRAY['Amazon represents','authority','enter into','Program','based on','underlying intellectual property','obtained','will obtain','all rights necessary','ProdCo','perform services']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Underlying IP rights representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Representation regarding underlying IP rights for which Amazon is responsible is appropriate where Amazon brings underlying rights to the relationship."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents it has authority to enter into this Agreement and to pay the fees set forth herein. Amazon''s payment obligations are not contingent on any third-party approvals, financing, or other conditions within Amazon''s control.', ARRAY['Amazon represents','authority','enter into','pay fees','payment obligations','not contingent','third-party approvals','financing','conditions','within Amazon''s control']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Payment authority representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Representation that payment isn''t contingent on third-party approvals provides ProdCo assurance of payment. Reasonable for production financing purposes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that: (a) it has authority to enter into this Agreement; (b) the person signing on behalf of Amazon is duly authorized; and (c) this Agreement, when executed, will be enforceable against Amazon in accordance with its terms, subject to customary bankruptcy and equitable exceptions.', ARRAY['Amazon represents','authority','enter into','person signing','duly authorized','enforceable','against Amazon','in accordance with terms','subject to','bankruptcy','equitable exceptions']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Execution authority with customary carveouts", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Signing authority and enforceability representations with customary bankruptcy/equity carveouts are standard commercial language. Legal should confirm scope is appropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents and warrants that it has full legal authority to enter into this Agreement and to perform all of its obligations hereunder, and that its performance will comply with all applicable laws. Amazon shall indemnify ProdCo against any losses arising from breach of these representations.', ARRAY['Amazon represents warrants','full legal authority','enter into','perform','all obligations','performance','comply','all applicable laws','indemnify','ProdCo','losses','breach']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Expansive Amazon representations with indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Expansive Amazon representation of ''all obligations'' compliance with ''all applicable laws'' plus indemnification to ProdCo far exceeds appropriate scope. Amazon provides limited indemnification per standard terms."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents and warrants that its exploitation of the Program will not infringe any third-party intellectual property rights, will not defame any person, and will not violate any right of privacy or publicity. Amazon shall indemnify and hold harmless ProdCo from any claims arising from such matters.', ARRAY['Amazon represents warrants','exploitation','Program','not infringe','intellectual property','not defame','not violate','privacy','publicity','indemnify','hold harmless','ProdCo','claims']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Amazon exploitation representations with full indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo is seeking to shift content liability to Amazon through mirror representations. Amazon''s indemnification scope is defined separately and doesn''t include ProdCo-created content issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon makes the same representations and warranties as ProdCo makes in Section [X], mutatis mutandis. The scope and nature of Amazon''s representations shall be equivalent to ProdCo''s representations in all material respects.', ARRAY['Amazon','same representations warranties','as ProdCo','mutatis mutandis','scope','nature','equivalent','all material respects']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Mirror representations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mirror representations ignore fundamental asymmetry between content creator (ProdCo) and commissioner/owner (Amazon). ProdCo''s content representations cannot be mirrored to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents that it has authority to enter into this Agreement. Amazon further represents that Amazon has conducted appropriate due diligence on the Program concept and has determined that the Program as conceived does not raise infringement, defamation, or privacy concerns.', ARRAY['Amazon represents','authority','enter into','conducted','due diligence','Program concept','determined','Program','does not raise','infringement','defamation','privacy concerns']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Amazon due diligence representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon representation of concept due diligence shifting content clearance responsibility to Amazon is completely unacceptable. ProdCo creates and clears the content."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents that it has authority to contract and that all Amazon executives approving this Agreement have appropriate delegation of authority. Amazon''s breach of this representation shall entitle ProdCo to void this Agreement and retain all payments received.', ARRAY['Amazon represents','authority','contract','executives approving','delegation of authority','breach','entitle ProdCo','void Agreement','retain','all payments']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Void and retain remedy", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Remedy allowing ProdCo to void Agreement and retain all payments for authority representation breach is grossly disproportionate to the representation scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents and warrants that: (a) Amazon has full authority to enter into this Agreement; (b) Amazon will maintain such authority throughout the term; (c) Amazon will not assign, delegate, or transfer any obligation that would impair ProdCo''s rights; and (d) Amazon will remain solvent and able to perform throughout the term.', ARRAY['Amazon represents warrants','full authority','maintain','throughout term','not assign','delegate','transfer','impair ProdCo''s rights','remain solvent','able to perform']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Expansive ongoing authority and solvency", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ongoing solvency representation and restriction on assignment/delegation go far beyond appropriate authority representation scope. Amazon''s assignment rights are addressed separately."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents that it has the right and power to perform this Agreement. ProdCo may request evidence of such authority, and Amazon shall provide copies of relevant board resolutions, delegation of authority policies, and financial statements upon request.', ARRAY['Amazon represents','right','power','perform','ProdCo may request','evidence','authority','provide copies','board resolutions','delegation','financial statements','upon request']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Documentation production requirement", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring Amazon to produce board resolutions, delegation policies, and financial statements to ProdCo is completely inappropriate. Amazon''s internal governance is confidential."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify, and at Amazon''s option defend, and hold harmless Amazon and its affiliates, and their respective officers, directors, employees, agents, successors, assigns, licensees and sublicensees (collectively, ''Amazon Indemnitees'') from and against any and all claims, damages, losses, costs and expenses (including reasonable attorneys'' fees) arising from or relating to any breach or alleged breach of ProdCo''s representations, warranties, covenants or obligations hereunder.', ARRAY['indemnify','at Amazon''s option defend','hold harmless','Amazon Indemnitees','affiliates','officers','directors','employees','agents','successors','assigns','licensees','sublicensees','claims','damages','losses','costs','expenses','attorneys'' fees','breach','alleged breach','representations','warranties','covenants','obligations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Standard comprehensive indemnity with defense option", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon indemnity with critical ''at Amazon''s option'' language for defense. Comprehensive indemnitee list and broad trigger coverage. Defense is at Amazon''s election, not ProdCo''s obligation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees to indemnify and hold harmless the Amazon Indemnitees from and against all Losses arising out of any third-party claim based upon any breach of ProdCo''s representations, warranties or obligations under this Agreement. At Amazon''s sole option, ProdCo shall defend any such claim with counsel reasonably acceptable to Amazon.', ARRAY['indemnify','hold harmless','Amazon Indemnitees','Losses','third-party claim','breach','representations','warranties','obligations','Amazon''s sole option','defend','counsel','reasonably acceptable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Defense at Amazon''s sole option with counsel approval", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''At Amazon''s sole option'' for defense is key. Counsel approval right ensures quality of defense. Standard formulation with defined ''Losses'' term."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall defend (at Amazon''s election), indemnify and hold harmless Amazon and all Amazon Indemnitees from any and all claims, actions, suits, proceedings, damages, liabilities, costs and expenses, including reasonable legal fees and costs of investigation, arising from or in connection with any breach by ProdCo of this Agreement.', ARRAY['defend','at Amazon''s election','indemnify','hold harmless','Amazon Indemnitees','claims','actions','suits','proceedings','damages','liabilities','costs','expenses','legal fees','investigation','breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Includes investigation costs", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes investigation costs in addition to legal fees. ''At Amazon''s election'' preserves Amazon''s right to control defense if preferred."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall fully indemnify, and if requested by Amazon shall defend, and shall hold harmless the Amazon Indemnitees from and against any and all Losses incurred by any Amazon Indemnitee arising out of or resulting from: (a) any breach of any representation or warranty made by ProdCo; (b) any breach of any covenant or obligation of ProdCo; or (c) any negligent or wrongful act or omission of ProdCo.', ARRAY['fully indemnify','if requested','defend','hold harmless','Losses','Amazon Indemnitee','breach','representation','warranty','covenant','obligation','negligent','wrongful act','omission']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Enumerated triggers with request-based defense", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''If requested by Amazon'' for defense is equivalent to ''at Amazon''s option.'' Enumerated triggers include negligence and wrongful acts. Comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby agrees to indemnify each Amazon Indemnitee and, at Amazon''s option, to defend each Amazon Indemnitee using legal counsel selected by ProdCo and approved by Amazon (such approval not to be unreasonably withheld), and to hold harmless each Amazon Indemnitee from and against all Losses arising from any Indemnified Claim.', ARRAY['indemnify','Amazon Indemnitee','at Amazon''s option','defend','legal counsel','selected by ProdCo','approved by Amazon','not unreasonably withheld','hold harmless','Losses','Indemnified Claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Counsel selection with Amazon approval", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo selects counsel with Amazon approval (NUBW standard). Preserves Amazon''s option on defense while allowing ProdCo to manage if Amazon elects."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall include: (i) the obligation to indemnify and hold harmless; (ii) at Amazon''s election, the obligation to defend with competent counsel; and (iii) the obligation to pay all Losses promptly upon demand. These obligations shall survive any termination or expiration of this Agreement.', ARRAY['indemnification obligations','indemnify','hold harmless','Amazon''s election','defend','competent counsel','pay all Losses','promptly','upon demand','survive','termination','expiration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Enumerated obligations with survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clearly enumerates indemnification components including prompt payment and survival. ''At Amazon''s election'' for defense is appropriate."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify, defend (if Amazon so elects), and hold harmless the Amazon Indemnitees from all Losses. If Amazon elects to have ProdCo defend a claim, ProdCo shall do so diligently and in good faith. If Amazon elects to conduct its own defense, ProdCo shall reimburse Amazon''s reasonable defense costs as part of Losses.', ARRAY['indemnify','defend','if Amazon elects','hold harmless','Losses','diligently','good faith','conduct own defense','reimburse','defense costs']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Both defense scenarios addressed", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses both scenarios: ProdCo defense (if elected) and Amazon self-defense (with reimbursement). Comprehensive and clear."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees from all Losses. At Amazon''s request, ProdCo shall defend any claim, provided that ProdCo shall have the right to select defense counsel subject to Amazon''s prior written approval, and Amazon shall have the right to participate in the defense at its own expense.', ARRAY['indemnify','hold harmless','Losses','at Amazon''s request','defend','right to select','defense counsel','prior written approval','participate','own expense']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon participation right added", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon participation right at own expense is reasonable addition that doesn''t limit ProdCo''s defense obligation. Counsel approval preserved. Legal should confirm."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees. If Amazon elects ProdCo defense, ProdCo shall defend using counsel experienced in entertainment industry litigation and acceptable to Amazon. ProdCo shall keep Amazon informed of material developments and shall not take any position adverse to Amazon''s interests.', ARRAY['indemnify','hold harmless','Amazon elects','ProdCo defense','counsel experienced','entertainment industry','acceptable','keep informed','material developments','not adverse','Amazon''s interests']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Qualified counsel with information rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Entertainment industry counsel requirement and information rights are reasonable additions. ''Not adverse to Amazon''s interests'' is appropriate protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify, defend (at Amazon''s option), and hold harmless the Amazon Indemnitees from all Losses. Notwithstanding the foregoing, ProdCo''s defense obligation shall not apply if Amazon has assumed defense of the claim, unless Amazon subsequently requests ProdCo to resume defense responsibilities.', ARRAY['indemnify','defend','at Amazon''s option','hold harmless','Losses','defense obligation','not apply','Amazon assumed defense','requests','resume defense']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Clarification of defense transition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification of defense transition when Amazon assumes control is reasonable procedural addition that doesn''t diminish indemnity protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees. At Amazon''s option, ProdCo shall defend any claim. If ProdCo is providing defense, Amazon may at any time elect to assume direct control of the defense, and ProdCo shall cooperate fully and continue to reimburse Losses.', ARRAY['indemnify','hold harmless','at Amazon''s option','defend','any time','assume direct control','cooperate fully','reimburse Losses']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon takeover right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s right to assume control at any time preserves Amazon''s flexibility. Continuing reimbursement obligation is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify, at Amazon''s election defend, and hold harmless Amazon Indemnitees from Losses. ProdCo shall maintain errors and omissions insurance with coverage of at least $5,000,000 per occurrence and $10,000,000 aggregate, which insurance shall provide primary coverage for Indemnified Claims.', ARRAY['indemnify','at Amazon''s election','defend','hold harmless','Losses','E&O insurance','$5,000,000','per occurrence','$10,000,000','aggregate','primary coverage','Indemnified Claims']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Insurance requirement added", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "E&O insurance requirement provides financial backing for indemnity obligations. Coverage amounts should be verified as adequate for production scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees from all Losses. At Amazon''s option, ProdCo shall defend. ProdCo acknowledges that its indemnity obligations are primary and not secondary or contingent upon any insurance coverage, and shall not be reduced by any insurance proceeds received by Amazon.', ARRAY['indemnify','hold harmless','Losses','at Amazon''s option','defend','primary','not secondary','not contingent','insurance','not reduced','insurance proceeds']::text[], '{"doc": "PSA_Fallbacks", "section": "Indemnification", "note": "Primary indemnity clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that indemnity is primary and not reduced by insurance is protective addition that addresses potential subrogation/set-off issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify, defend and hold harmless the Amazon Indemnitees from all Losses. ProdCo shall assume the defense of any claim and shall have sole control of the defense and settlement. Amazon shall not have the right to participate in or direct the defense.', ARRAY['indemnify','defend','hold harmless','Losses','assume defense','sole control','defense','settlement','Amazon','no right','participate','direct']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Mandatory defense with ProdCo sole control", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Removing Amazon''s option on defense and giving ProdCo ''sole control'' eliminates Amazon''s ability to manage claims affecting its interests. Amazon must retain defense election right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless Amazon from Losses, but shall not be obligated to defend any claim. Amazon shall conduct its own defense and may seek reimbursement of defense costs from ProdCo as part of Losses.', ARRAY['indemnify','hold harmless','Losses','not obligated','defend','Amazon conduct','own defense','seek reimbursement','defense costs']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "No defense obligation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating defense obligation entirely forces Amazon to manage all defenses and seek reimbursement. Amazon should have option to have ProdCo defend at ProdCo''s cost."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify the Amazon Indemnitees from Losses to the extent such Losses exceed ProdCo''s errors and omissions insurance coverage. ProdCo''s indemnification obligation shall be limited to Losses in excess of $100,000 per claim.', ARRAY['indemnify','Losses','to the extent','exceed','E&O insurance','limited','excess of','$100,000','per claim']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Insurance excess and dollar floor", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making indemnity excess over insurance and imposing $100K floor shifts significant risk to Amazon. Indemnity must be first-dollar and primary, not excess."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless Amazon from third-party claims to the extent finally adjudicated to arise from ProdCo''s breach. ProdCo shall have no indemnification obligation for claims that are settled prior to final judgment or for claims that are dismissed.', ARRAY['indemnify','hold harmless','third-party claims','finally adjudicated','breach','no obligation','settled','prior to judgment','dismissed']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Final adjudication requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ''final adjudication'' before indemnity applies eliminates coverage for settlements (vast majority of claims) and dismissed claims. Completely unworkable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon from Losses arising from ProdCo''s gross negligence or willful misconduct only. Ordinary negligence, inadvertent breaches, and unintentional errors shall not trigger ProdCo''s indemnification obligations.', ARRAY['indemnify','Losses','gross negligence','willful misconduct','only','ordinary negligence','inadvertent breaches','unintentional errors','not trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Limited to gross negligence/willful misconduct", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnity to gross negligence/willful misconduct excludes most breach scenarios. Indemnity must cover all breaches regardless of intent or negligence level."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon from Losses. ProdCo''s aggregate liability under this indemnification provision shall not exceed the total fees paid to ProdCo under this Agreement. This limitation shall apply regardless of the nature or number of claims.', ARRAY['indemnify','Losses','aggregate liability','not exceed','total fees paid','limitation','regardless','nature','number of claims']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Cap at fees paid", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping indemnity at fees paid could leave Amazon massively underprotected for significant claims. Production fees don''t correlate to potential claim exposure. No cap is acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall indemnify and hold harmless the other from Losses arising from such party''s breach of this Agreement. The parties'' indemnification obligations shall be mutual and equivalent in all respects.', ARRAY['each party','indemnify','hold harmless','Losses','breach','mutual','equivalent','all respects']::text[], '{"doc": "Counterparty_Proposal", "section": "Indemnification", "note": "Forced mutual equivalent indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced mutual equivalent indemnity ignores fundamental asymmetry. ProdCo creates content that generates claims; Amazon''s indemnity scope is properly limited. Equivalence is inappropriate."}'::jsonb)
